    // ---------- Network helpers (Cloudflare-aware) ----------
    // Plain request first; if the site answers with a Cloudflare challenge
    // (403/503 or the "Just a moment" interstitial) the request is retried
    // through CloudStream's CloudflareKiller. Works for any site and costs
    // nothing on sites that are not protected.
    private val cfKiller by lazy { CloudflareKiller() }

    private fun looksBlocked(code: Int, body: String): Boolean =
        code == 403 || code == 503 ||
            (body.length < 8000 && BLOCK_MARKERS.any { body.contains(it, true) })

    private suspend fun fetchHtml(url: String, referer: String? = null): String {
        val headers = getHeaders() + mapOf("Referer" to (referer ?: "$mainUrl/"))
        val first = try { app.get(url, headers = headers) } catch (_: Exception) { null }
        if (first != null && !looksBlocked(first.code, first.text)) return first.text
        return try {
            app.get(url, headers = headers, interceptor = cfKiller).text
        } catch (_: Exception) {
            first?.text.orEmpty()
        }
    }

    private suspend fun getDoc(url: String, referer: String? = null): org.jsoup.nodes.Document =
